import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const easeOutClass = "ease-[cubic-bezier(0.23,1,0.32,1)]";

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

export function edgeOffset(placement: string | null, distance: number) {
  switch (placement) {
    case "top":
      return { x: 0, y: distance };
    case "left":
      return { x: distance, y: 0 };
    case "right":
      return { x: -distance, y: 0 };
    default:
      return { x: 0, y: -distance };
  }
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] transition-[color,background-color,border-color,box-shadow,scale] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] disabled:cursor-default disabled:opacity-50 disabled:shadow-none focus-visible:outline-2 focus-visible:outline-offset-3 focus-visible:outline-ring [&_svg]:pointer-events-none [&_svg]:shrink-0",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 pressed:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 pressed:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted pressed:bg-muted",
      ghost:
        "text-foreground hover:bg-muted pressed:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
      minimal:
        "text-muted-foreground hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 pressed:bg-destructive/90",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import { springLayout } from "./motion";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

const pressStyles = "motion-safe:pressed:not-aria-expanded:scale-[0.96]";

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      layout={reduceMotion ? false : layout}
      transition={springLayout}
      className={composeRenderProps(className, (className) =>
        buttonStyles({
          variant,
          size,
          className: [!isStatic && pressStyles, className],
        }),
      )}
      {...props}
    />
  );
}

"use client";

import { CheckIcon, MinusIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import { createContext, useContext, useState } from "react";
import {
  Checkbox as AriaCheckbox,
  type CheckboxProps as AriaCheckboxProps,
  composeRenderProps,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";

const CheckboxStateContext = createContext({
  isSelected: false,
  isIndeterminate: false,
  isHovered: false,
  isPressed: false,
});

export interface CheckboxProps
  extends Omit<AriaCheckboxProps, "className" | "children"> {
  ref?: React.Ref<HTMLLabelElement>;
  className?: AriaCheckboxProps["className"];
  description?: string;
  children?: AriaCheckboxProps["children"];
  checked?: boolean | "indeterminate";
  defaultChecked?: boolean | "indeterminate";
  onCheckedChange?: (checked: boolean) => void;
}

export function Checkbox({
  children,
  description,
  className,
  checked,
  defaultChecked,
  onCheckedChange,
  ...props
}: CheckboxProps) {
  const [initialIndeterminate, setInitialIndeterminate] = useState(
    defaultChecked === "indeterminate",
  );
  return (
    <AriaCheckbox
      {...props}
      isSelected={checked === undefined ? props.isSelected : checked === true}
      defaultSelected={
        defaultChecked === undefined
          ? props.defaultSelected
          : defaultChecked === true
      }
      isIndeterminate={
        checked === undefined
          ? initialIndeterminate || props.isIndeterminate
          : checked === "indeterminate"
      }
      onChange={(value) => {
        setInitialIndeterminate(false);
        props.onChange?.(value);
        onCheckedChange?.(value);
      }}
      data-slot="checkbox"
      className={composeRenderProps(className, (className) =>
        cn(
          "group inline-flex min-h-11 cursor-pointer items-start gap-3 rounded-md text-sm text-foreground disabled:cursor-default disabled:opacity-50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
          typeof children === "string" && !description && "items-center",
          className,
        ),
      )}
    >
      {(state) => (
        <CheckboxStateContext.Provider value={state}>
          {typeof children === "function" ? (
            children(state)
          ) : typeof children === "string" || children == null ? (
            <>
              <CheckboxIndicator />
              {(children || description) && (
                <span className="pt-0.5">
                  {children && (
                    <span className="block font-medium">{children}</span>
                  )}
                  {description && (
                    <span className="mt-1 block text-xs leading-5 text-muted-foreground">
                      {description}
                    </span>
                  )}
                </span>
              )}
            </>
          ) : (
            children
          )}
        </CheckboxStateContext.Provider>
      )}
    </AriaCheckbox>
  );
}

export function CheckboxIndicator({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  const { isSelected, isIndeterminate, isHovered, isPressed } =
    useContext(CheckboxStateContext);
  const reduceMotion = useReducedMotion();
  const isChecked = isSelected || isIndeterminate;
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="checkbox-indicator"
      className={cn(
        "mt-0.5 grid size-5 shrink-0 place-items-center rounded-md border border-input bg-card shadow-[var(--shadow-inset)] transition-[background-color,border-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] group-hover:border-primary/60 group-invalid:border-destructive group-invalid:group-hover:border-destructive group-selected:border-primary group-selected:bg-primary group-indeterminate:border-primary group-indeterminate:bg-primary",
        className,
      )}
    >
      <motion.span
        initial={false}
        animate={{
          scale: isChecked ? (isPressed ? 0.9 : isHovered ? 1.06 : 1) : 0.86,
          opacity: isChecked ? 1 : 0,
        }}
        transition={{
          duration: reduceMotion ? 0 : duration.fast,
          ease: easeOut,
        }}
        className="text-primary-foreground"
      >
        {isIndeterminate ? (
          <MinusIcon size={13} weight="bold" />
        ) : (
          <CheckIcon size={13} weight="bold" />
        )}
      </motion.span>
    </span>
  );
}

export function CheckboxLabel({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="checkbox-label"
      className={cn("block font-medium", className)}
    />
  );
}

export function CheckboxDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="checkbox-description"
      className={cn(
        "mt-1 block text-xs leading-5 text-muted-foreground",
        className,
      )}
    />
  );
}

export const fieldLabelStyles = "text-sm font-medium text-foreground";
export const fieldDescriptionStyles = "text-xs leading-5 text-muted-foreground";
export const fieldErrorStyles = "text-xs leading-5 text-destructive";

export const fieldInputStyles =
  "min-h-12 w-full cursor-text rounded-lg border border-input bg-card text-base text-foreground shadow-[var(--shadow-card)] outline-none transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] placeholder:text-muted-foreground/80 hover:border-primary/45 focus:border-ring focus:ring-3 focus:ring-ring/50 invalid:border-destructive invalid:ring-3 invalid:ring-destructive/20 invalid:hover:border-destructive invalid:focus:border-destructive invalid:focus:ring-destructive/30 [&[readonly]]:bg-muted/40 [&[readonly]]:hover:border-input disabled:cursor-not-allowed disabled:bg-muted disabled:opacity-60 disabled:hover:border-input sm:text-sm";

export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:border-primary/45 focus-within:border-ring focus-within:hover:border-ring focus-within:ring-3 focus-within:ring-ring/50 group-invalid:border-destructive group-invalid:ring-3 group-invalid:ring-destructive/20 group-invalid:hover:border-destructive group-invalid:focus-within:border-destructive group-invalid:focus-within:hover:border-destructive group-invalid:focus-within:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-disabled:bg-muted group-disabled:opacity-60 group-disabled:hover:border-input";

export const fieldTriggerStyles =
  "grid size-11 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none transition-[color,background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring disabled:cursor-default disabled:opacity-50";

"use client";

import { MagnifyingGlassIcon, XIcon } from "@phosphor-icons/react";
import {
  Button as AriaButton,
  SearchField as AriaSearchField,
  type SearchFieldProps as AriaSearchFieldProps,
  composeRenderProps,
  FieldError,
  Input,
  Label,
  Text,
} from "react-aria-components";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldInputStyles,
  fieldLabelStyles,
  fieldTriggerStyles,
} from "./field-styles";

export interface SearchFieldProps
  extends Omit<AriaSearchFieldProps, "children" | "className"> {
  label?: string;
  description?: string;
  placeholder?: string;
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaSearchFieldProps["className"];
  children?: AriaSearchFieldProps["children"];
}

export function SearchField({
  label,
  description,
  placeholder,
  className,
  children,
  ...props
}: SearchFieldProps) {
  return (
    <AriaSearchField
      {...props}
      data-slot="search-field"
      className={composeRenderProps(className, (className) =>
        cn("group flex w-full flex-col gap-2", className),
      )}
    >
      {children ??
        (({ isEmpty }) => (
          <>
            {label && <SearchFieldLabel>{label}</SearchFieldLabel>}
            <div className="relative flex items-center">
              <MagnifyingGlassIcon
                size={17}
                aria-hidden="true"
                className="pointer-events-none absolute start-3.5 text-muted-foreground group-disabled:opacity-60"
              />
              <SearchFieldInput placeholder={placeholder} />
              {!isEmpty && <SearchFieldClear />}
            </div>
            {description && (
              <SearchFieldDescription>{description}</SearchFieldDescription>
            )}
            <SearchFieldError />
          </>
        ))}
    </AriaSearchField>
  );
}

export function SearchFieldLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="search-field-label"
      className={cn(fieldLabelStyles, className)}
    />
  );
}

export function SearchFieldInput({
  className,
  ...props
}: React.ComponentProps<typeof Input>) {
  return (
    <Input
      {...props}
      data-slot="search-field-input"
      className={composeRenderProps(className, (className) =>
        cn(
          fieldInputStyles,
          "ps-10 pe-12 [&::-webkit-search-cancel-button]:hidden",
          className,
        ),
      )}
    />
  );
}

export function SearchFieldClear({
  className,
  children,
  ...props
}: React.ComponentProps<typeof AriaButton>) {
  return (
    <AriaButton
      {...props}
      data-slot="search-field-clear"
      aria-label={props["aria-label"] ?? "Clear search"}
      className={composeRenderProps(className, (className) =>
        cn(
          fieldTriggerStyles,
          "absolute inset-y-0 end-1 my-auto group-empty:hidden",
          className,
        ),
      )}
    >
      {children ?? <XIcon size={16} aria-hidden="true" />}
    </AriaButton>
  );
}

export function SearchFieldDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="search-field-description"
      className={cn(fieldDescriptionStyles, className)}
    />
  );
}

export function SearchFieldError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="search-field-error"
      className={cn(fieldErrorStyles, className)}
    />
  );
}

"use client";

import { CheckIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import {
  ListBox as AriaListBox,
  ListBoxItem as AriaListBoxItem,
  composeRenderProps,
  type ListBoxItemProps,
  type ListBoxProps,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";

export function ListBox<T extends object>({
  className,
  ...props
}: ListBoxProps<T>) {
  return (
    <AriaListBox
      {...props}
      data-slot="list-box"
      className={composeRenderProps(className, (className) =>
        cn(
          "grid max-h-72 w-full gap-1 overflow-y-auto rounded-lg border border-border bg-card p-1.5 shadow-[var(--shadow-card)] outline-none",
          className,
        ),
      )}
    />
  );
}

export function ListBoxItem({
  className,
  children,
  ...props
}: ListBoxItemProps) {
  return (
    <AriaListBoxItem
      {...props}
      data-slot="list-box-item"
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-3 text-sm text-foreground outline-none hover:bg-muted focus:bg-muted selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50 focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ring",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {content}
          <SelectionMark isSelected={isSelected} />
        </>
      ))}
    </AriaListBoxItem>
  );
}

export function SelectionMark({
  isSelected,
  className,
}: {
  isSelected: boolean;
  className?: string;
}) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.span
      aria-hidden="true"
      className={cn("ms-auto shrink-0", className)}
      initial={false}
      animate={{ opacity: isSelected ? 1 : 0, scale: isSelected ? 1 : 0.85 }}
      transition={{ duration: reduceMotion ? 0 : duration.fast, ease: easeOut }}
    >
      <CheckIcon size={16} weight="bold" />
    </motion.span>
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import {
  Popover as AriaPopover,
  composeRenderProps,
  type PopoverProps,
} from "react-aria-components";
import { easeOut, edgeOffset } from "./motion";
import { cn } from "./utils";

type StyledPopoverProps = PopoverProps & { "data-slot"?: string };

export function Popover({
  className,
  "data-slot": dataSlot = "popover",
  ...props
}: StyledPopoverProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      render={
        props.render ??
        ((domProps, { placement, isExiting }) => (
          <motion.div
            {...(domProps as HTMLMotionProps<"div">)}
            initial={
              reduceMotion || props.shouldSkipAnimation
                ? false
                : { opacity: 0, ...edgeOffset(placement, 5), scale: 0.98 }
            }
            animate={
              isExiting
                ? {
                    opacity: 0,
                    ...(reduceMotion ? {} : edgeOffset(placement, 5)),
                    scale: reduceMotion ? 1 : 0.99,
                  }
                : { opacity: 1, x: 0, y: 0, scale: 1 }
            }
            transition={{
              duration: reduceMotion ? 0 : isExiting ? 0.14 : 0.2,
              ease: easeOut,
            }}
          />
        ))
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "max-w-[calc(100vw-2rem)] overflow-auto overscroll-contain rounded-xl border border-border bg-popover p-5 text-popover-foreground shadow-[var(--shadow-float)] outline-none data-[placement=top]:origin-bottom data-[placement=bottom]:origin-top data-[placement=left]:origin-right data-[placement=right]:origin-left",
          className,
        ),
      )}
    />
  );
}

"use client";

import { type HTMLMotionProps, motion, useReducedMotion } from "motion/react";
import { Button, type ButtonProps } from "react-aria-components";

export function PressButton({ isDisabled, ...props }: ButtonProps) {
  const reduceMotion = useReducedMotion();

  return (
    <Button
      data-slot="press-button"
      {...props}
      isDisabled={isDisabled}
      render={
        props.render ??
        ((domProps) => (
          <motion.button
            {...(domProps as HTMLMotionProps<"button">)}
            whileTap={reduceMotion || isDisabled ? undefined : { scale: 0.96 }}
            transition={{ type: "spring", stiffness: 500, damping: 36 }}
          />
        ))
      }
    />
  );
}

"use client";

import { CaretDownIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import { type ReactNode, useContext } from "react";
import {
  type Button as AriaButton,
  Select as AriaSelect,
  type SelectProps as AriaSelectProps,
  SelectValue as AriaSelectValue,
  composeRenderProps,
  FieldError,
  Label,
  ListBox,
  ListBoxItem,
  SelectStateContext,
  Text,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldLabelStyles,
} from "./field-styles";
import { SelectionMark } from "./list-box";
import { Popover } from "./popover";
import { PressButton } from "./press-button";

const selectTriggerStyles =
  "relative flex min-h-12 w-full min-w-0 cursor-pointer items-center rounded-lg border border-input bg-card ps-3.5 pe-10 text-start text-base leading-6 text-foreground shadow-[var(--shadow-card)] outline-none transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:border-primary/45 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 group-invalid:border-destructive group-invalid:ring-3 group-invalid:ring-destructive/20 group-invalid:hover:border-destructive group-invalid:focus-visible:border-destructive group-invalid:focus-visible:ring-destructive/30 disabled:cursor-default disabled:bg-muted disabled:opacity-60 sm:text-sm sm:leading-5";
const selectValueStyles =
  "min-w-0 flex-1 self-center truncate text-start data-[placeholder]:text-muted-foreground";
const selectItemStyles =
  "group/item flex min-h-11 cursor-pointer items-center justify-between gap-3 rounded-md px-2.5 py-2 text-sm outline-none hover:bg-muted focus:bg-muted selected:bg-accent selected:text-accent-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-default disabled:opacity-50";
const selectPopoverStyles =
  "w-[var(--trigger-width)] rounded-lg border-0 p-1.5 ring-1 ring-border/70";

export interface SelectOption {
  id: string;
  name: string;
  description?: string;
}
export interface SelectProps
  extends Omit<AriaSelectProps<SelectOption>, "children" | "className"> {
  label?: string;
  description?: string;
  options?: SelectOption[];
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaSelectProps<SelectOption>["className"];
  children?: AriaSelectProps<SelectOption>["children"];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export function Select({
  label,
  description,
  options,
  className,
  children,
  value,
  defaultValue,
  onValueChange,
  placeholder = "Select an option",
  ...props
}: SelectProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaSelect
      {...props}
      data-slot="select"
      selectedKey={value ?? props.selectedKey}
      defaultSelectedKey={defaultValue ?? props.defaultSelectedKey}
      onSelectionChange={(key) => {
        props.onSelectionChange?.(key);
        onValueChange?.(key === null ? "" : String(key));
      }}
      placeholder={placeholder}
      className={composeRenderProps(className, (className) =>
        cn("group flex w-full min-w-0 flex-col gap-2", className),
      )}
    >
      {children ??
        (({ isOpen }) => (
          <>
            {label && (
              <Label data-slot="select-label" className={fieldLabelStyles}>
                {label}
              </Label>
            )}
            <PressButton
              data-slot="select-trigger"
              className={selectTriggerStyles}
            >
              <AriaSelectValue
                data-slot="select-value"
                className={selectValueStyles}
              >
                {({ selectedText, isPlaceholder, state }) =>
                  isPlaceholder
                    ? placeholder
                    : (options?.find(
                        (option) => option.id === state.selectedKey,
                      )?.name ?? selectedText)
                }
              </AriaSelectValue>
              <SelectChevron open={isOpen} reduceMotion={reduceMotion} />
            </PressButton>
            {description && (
              <Text
                slot="description"
                data-slot="select-description"
                className={fieldDescriptionStyles}
              >
                {description}
              </Text>
            )}
            <SelectError />
            <Popover
              data-slot="select-content"
              placement="bottom start"
              offset={7}
              maxHeight={268}
              className={selectPopoverStyles}
            >
              <ListBox
                data-slot="select-list-box"
                items={options ?? []}
                className="grid gap-1 outline-none"
              >
                {(option) => (
                  <ListBoxItem
                    data-slot="select-item"
                    id={option.id}
                    textValue={option.name}
                    className={selectItemStyles}
                  >
                    {({ isSelected }) => (
                      <>
                        <span className="min-w-0">
                          <span className="block font-medium">
                            {option.name}
                          </span>
                          {option.description && (
                            <span className="mt-0.5 block text-xs text-muted-foreground group-selected/item:text-accent-foreground">
                              {option.description}
                            </span>
                          )}
                        </span>
                        <SelectionMark isSelected={isSelected} />
                      </>
                    )}
                  </ListBoxItem>
                )}
              </ListBox>
            </Popover>
          </>
        ))}
    </AriaSelect>
  );
}

